def truncate_and_normalize(text: str, max_len: int = 50) -> str:
    if not isinstance(text, str):
        raise TypeError("Input text must be a string")
    cleaned = " ".join(text.split()).strip()
    if len(cleaned) <= max_len:
        return cleaned
    return cleaned[:max_len]

